d=json.load(open(P,encoding='utf-8'))
ids=set(); ents=set()
for f in glob.glob('/home/claude/ueno-kg/data/raw/*.jsonl'):
    for l in open(f,encoding='utf-8'):
        if l.strip():
            r=json.loads(l); ids.add(r['id'])
            if '.entities.' in f: ents.add(r['id'])
            for k in ('from','to','holder','org','borrower','lender','entity'):
                if r.get(k): ents.add(r[k])
bad=[];bade=[];n=0
def chk(refs,where):
    global n
    if not refs: bad.append((where,'EMPTY'))
    for x in refs:
        n+=1
        if x not in ids: bad.append((where,x))
for c in d['chains']:
    for l in c['legs']:
        chk(l['refs'],c['id']+'#%d'%l['step'])
        for e in (l['from'],l['to']):
            if e not in ents: bade.append(e)
for t in d['typologies']:
    for i in t['indicators_present']: chk(i['refs'],t['name_en'][:20])
    assert len(t['indicators_absent_en'])==len(t['indicators_absent_es'])
for r in d['red_flags']: chk(r['refs'],r['date'])
for o in d['opinions']: chk(o['basis_refs'],'op')
for h in d['hubs']:
    if h['entity'] not in ents: bade.append(h['entity'])
assert len(d['next_tests_en'])==len(d['next_tests_es'])
print('refs checked',n,'bad',bad,'bad entities',bade)
print('chains',len(d['chains']),'legs',sum(len(c['legs']) for c in d['chains']),'hubs',len(d['hubs']),'typ',len(d['typologies']),'red',len(d['red_flags']),'ops',len(d['opinions']),'tests',len(d['next_tests_en']))
